import React, { useEffect, useState, useMemo, useCallback } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from '../../api/axios';
import { NavigationBar } from '../../components/Home/NavigationBar';
import '../../styles/AdminProducts.css';

const CATEGORIES = [
  'Grocery',
  'Apparel',
  'Shoes',
  'Books',
  'Sports',
  'Furniture',
  'Stationery',
  'Plants',
  'Bakery'
];

const INITIAL_FORM_STATE = {
  name: '',
  description: '',
  price: '',
  originalPrice: '',
  image: '',
  category: 'Grocery',
  subcategory: '',
  stock: '',
  featured: false,
  isNew: false
};

const AdminProducts = ({ theme, onToggleTheme }) => {
  const navigate = useNavigate();
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [toasts, setToasts] = useState([]);

  // Filter/Sort States
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [stockFilter, setStockFilter] = useState('all');
  const [sortBy, setSortBy] = useState('name');

  // Modal States
  const [showModal, setShowModal] = useState(null); // 'add', 'edit', 'delete'
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [formData, setFormData] = useState(INITIAL_FORM_STATE);
  const [formErrors, setFormErrors] = useState({});

  // ── Toast Helper ─────────────────────────────────────────────────
  const addToast = useCallback((message, type = 'success') => {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4000);
  }, []);

  // ── Fetch Products ───────────────────────────────────────────────
  const fetchProducts = useCallback(async () => {
    try {
      setLoading(true);
      const { data } = await axios.get('/api/products', { params: { limit: 500 } });
      if (data && Array.isArray(data.products)) {
        setProducts(data.products);
      }
    } catch (err) {
      addToast('Failed to load products from server. Using fallbacks.', 'error');
    } finally {
      setLoading(false);
    }
  }, [addToast]);

  useEffect(() => {
    fetchProducts();
  }, [fetchProducts]);

  // ── Form Validation ──────────────────────────────────────────────
  const validateForm = () => {
    const errors = {};
    if (!formData.name.trim()) errors.name = 'Product name is required';
    if (!formData.price || Number(formData.price) <= 0) {
      errors.price = 'Price must be a positive number';
    }
    if (formData.originalPrice && Number(formData.originalPrice) < Number(formData.price)) {
      errors.originalPrice = 'Original price should be higher than selling price';
    }
    if (!formData.category) errors.category = 'Category is required';
    if (formData.stock === '' || Number(formData.stock) < 0) {
      errors.stock = 'Stock cannot be negative';
    }
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  // ── Open Modals ──────────────────────────────────────────────────
  const handleOpenAdd = () => {
    setFormData(INITIAL_FORM_STATE);
    setFormErrors({});
    setShowModal('add');
  };

  const handleOpenEdit = (product) => {
    setSelectedProduct(product);
    setFormData({
      name: product.name || '',
      description: product.description || '',
      price: product.price || '',
      originalPrice: product.originalPrice || '',
      image: product.image || '',
      category: product.category || 'Grocery',
      subcategory: product.subcategory || '',
      stock: product.stock !== undefined ? product.stock : 0,
      featured: !!product.featured,
      isNew: !!product.isNew
    });
    setFormErrors({});
    setShowModal('edit');
  };

  const handleOpenDelete = (product) => {
    setSelectedProduct(product);
    setShowModal('delete');
  };

  const handleCloseModal = () => {
    setShowModal(null);
    setSelectedProduct(null);
    setFormData(INITIAL_FORM_STATE);
    setFormErrors({});
  };

  // ── Save/Create Handler ──────────────────────────────────────────
  const handleSave = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;

    const payload = {
      ...formData,
      price: Number(formData.price),
      originalPrice: formData.originalPrice ? Number(formData.originalPrice) : undefined,
      stock: Number(formData.stock),
      discount: formData.originalPrice 
        ? `${Math.round(((formData.originalPrice - formData.price) / formData.originalPrice) * 100)}% OFF`
        : ''
    };

    try {
      setSaving(true);
      if (showModal === 'add') {
        const { data } = await axios.post('/api/products', payload);
        if (data.success) {
          addToast(`Successfully created ${payload.name}`);
          fetchProducts();
          handleCloseModal();
        }
      } else if (showModal === 'edit') {
        const { data } = await axios.put(`/api/products/${selectedProduct._id}`, payload);
        if (data.success) {
          addToast(`Successfully updated ${payload.name}`);
          fetchProducts();
          handleCloseModal();
        }
      }
    } catch (err) {
      addToast(err.response?.data?.message || 'Error processing request', 'error');
    } finally {
      setSaving(false);
    }
  };

  // ── Delete Handler ───────────────────────────────────────────────
  const handleDelete = async () => {
    try {
      setSaving(true);
      const { data } = await axios.delete(`/api/products/${selectedProduct._id}`);
      if (data.success) {
        addToast(`Successfully deleted ${selectedProduct.name}`);
        fetchProducts();
        handleCloseModal();
      }
    } catch (err) {
      addToast('Error deleting product', 'error');
    } finally {
      setSaving(false);
    }
  };

  // ── Stats Calculations ───────────────────────────────────────────
  const stats = useMemo(() => {
    const total = products.length;
    const outOfStock = products.filter((p) => Number(p.stock || 0) === 0).length;
    const lowStock = products.filter((p) => Number(p.stock || 0) > 0 && Number(p.stock || 0) <= 10).length;
    const uniqueCategories = new Set(products.map((p) => p.category)).size;

    return { total, outOfStock, lowStock, uniqueCategories };
  }, [products]);

  // ── Filters & Search Logic ───────────────────────────────────────
  const filteredProducts = useMemo(() => {
    let result = [...products];

    // 1. Search filter
    if (searchQuery.trim()) {
      const searchRegex = new RegExp(searchQuery.trim(), 'i');
      result = result.filter(
        (p) => searchRegex.test(p.name) || searchRegex.test(p.category) || searchRegex.test(p.description)
      );
    }

    // 2. Category filter
    if (categoryFilter !== 'all') {
      result = result.filter((p) => p.category === categoryFilter);
    }

    // 3. Stock filter
    if (stockFilter === 'out') {
      result = result.filter((p) => Number(p.stock || 0) === 0);
    } else if (stockFilter === 'low') {
      result = result.filter((p) => Number(p.stock || 0) > 0 && Number(p.stock || 0) <= 10);
    } else if (stockFilter === 'in') {
      result = result.filter((p) => Number(p.stock || 0) > 10);
    }

    // 4. Sort logic
    if (sortBy === 'name') {
      result.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortBy === 'price_asc') {
      result.sort((a, b) => a.price - b.price);
    } else if (sortBy === 'price_desc') {
      result.sort((a, b) => b.price - a.price);
    } else if (sortBy === 'stock') {
      result.sort((a, b) => a.stock - b.stock);
    } else if (sortBy === 'sold') {
      result.sort((a, b) => b.sold - a.sold);
    }

    return result;
  }, [products, searchQuery, categoryFilter, stockFilter, sortBy]);

  return (
    <div className="page-wrapper">
      <NavigationBar theme={theme} onToggleTheme={onToggleTheme} />

      <div className="admin-products-page">
        {/* Header */}
        <header className="admin-header">
          <div className="admin-header-title">
            <h1>Product Inventory Manager</h1>
            <p>Add, edit, delete, and monitor catalog levels</p>
          </div>
          <button className="btn btn-primary" onClick={handleOpenAdd}>
            ➕ Add New Product
          </button>
        </header>

        {/* Stats Grid */}
        <section className="admin-stats-grid">
          <div className="admin-stat-card">
            <div className="admin-stat-icon total">📦</div>
            <div className="admin-stat-info">
              <h3>Total Items</h3>
              <p>{stats.total}</p>
            </div>
          </div>
          <div className="admin-stat-card">
            <div className="admin-stat-icon out-stock">🚨</div>
            <div className="admin-stat-info">
              <h3>Out of Stock</h3>
              <p>{stats.outOfStock}</p>
            </div>
          </div>
          <div className="admin-stat-card">
            <div className="admin-stat-icon low-stock">⚠️</div>
            <div className="admin-stat-info">
              <h3>Low Stock</h3>
              <p>{stats.lowStock}</p>
            </div>
          </div>
          <div className="admin-stat-card">
            <div className="admin-stat-icon categories">🌿</div>
            <div className="admin-stat-info">
              <h3>Categories</h3>
              <p>{stats.uniqueCategories}</p>
            </div>
          </div>
        </section>

        {/* Filter Controls Card */}
        <section className="admin-controls-card">
          <div className="admin-controls-grid">
            <div className="admin-search-wrapper">
              <span className="admin-search-icon">🔍</span>
              <input
                type="text"
                placeholder="Search products by name or info..."
                className="admin-input-search"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>

            <select
              className="admin-select"
              value={categoryFilter}
              onChange={(e) => setCategoryFilter(e.target.value)}
            >
              <option value="all">All Categories</option>
              {CATEGORIES.map((cat) => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>

            <select
              className="admin-select"
              value={stockFilter}
              onChange={(e) => setStockFilter(e.target.value)}
            >
              <option value="all">All Inventory</option>
              <option value="in">In Stock (&gt;10)</option>
              <option value="low">Low Stock (1-10)</option>
              <option value="out">Out of Stock (0)</option>
            </select>

            <select
              className="admin-select"
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
            >
              <option value="name">Sort: Name A-Z</option>
              <option value="price_asc">Sort: Price Low → High</option>
              <option value="price_desc">Sort: Price High → Low</option>
              <option value="stock">Sort: Stock Level</option>
              <option value="sold">Sort: Popularity</option>
            </select>
          </div>
        </section>

        {/* Inventory Table */}
        <section className="admin-table-card">
          {loading ? (
            <div style={{ textAlign: 'center', padding: '60px' }}>
              <div className="spinner" style={{ margin: '0 auto 16px' }} />
              <p>Fetching inventory records...</p>
            </div>
          ) : filteredProducts.length === 0 ? (
            <div className="admin-empty-state">
              <h3>😕 No Products Found</h3>
              <p>Try clearing your filters or create a new product to populate the records.</p>
            </div>
          ) : (
            <div className="admin-table-wrapper">
              <table className="admin-table">
                <thead>
                  <tr>
                    <th>Product</th>
                    <th>Category</th>
                    <th>Price</th>
                    <th>Stock</th>
                    <th>Tags</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredProducts.map((p) => {
                    const isOutOfStock = Number(p.stock || 0) === 0;
                    const isLowStock = Number(p.stock || 0) > 0 && Number(p.stock || 0) <= 10;

                    return (
                      <tr key={p._id}>
                        <td>
                          <div className="product-cell">
                            <img
                              src={p.image || 'https://via.placeholder.com/150'}
                              alt={p.name}
                              className="product-cell-img"
                              onError={(e) => {
                                e.target.onerror = null;
                                e.target.src = 'https://via.placeholder.com/150';
                              }}
                            />
                            <div>
                              <p className="product-cell-name">{p.name}</p>
                              <p className="product-cell-sub">{p.subcategory || 'General'}</p>
                            </div>
                          </div>
                        </td>
                        <td>
                          <span style={{ fontSize: '0.85rem', fontWeight: 600 }}>{p.category}</span>
                        </td>
                        <td>
                          <span className="price-actual">₹{Number(p.price || 0).toFixed(2)}</span>
                          {p.originalPrice && (
                            <span className="price-original">₹{Number(p.originalPrice).toFixed(0)}</span>
                          )}
                        </td>
                        <td>
                          <span className={`badge-stock ${isOutOfStock ? 'out-stock' : isLowStock ? 'low-stock' : 'in-stock'}`}>
                            {isOutOfStock ? 'Out of Stock' : isLowStock ? `${p.stock} Left` : `${p.stock} Units`}
                          </span>
                        </td>
                        <td>
                          {p.featured && <span className="badge-featured">Featured</span>}
                          {p.isNew && <span className="badge-new">New</span>}
                          {!p.featured && !p.isNew && <span style={{ color: 'var(--admin-text-muted)', fontSize: '0.85rem' }}>-</span>}
                        </td>
                        <td>
                          <div className="actions-cell">
                            <button
                              className="btn btn-secondary btn-icon"
                              title="Edit Product"
                              onClick={() => handleOpenEdit(p)}
                            >
                              ✏️
                            </button>
                            <button
                              className="btn btn-danger btn-icon"
                              title="Delete Product"
                              onClick={() => handleOpenDelete(p)}
                            >
                              🗑️
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </section>

        {/* Add/Edit Modal */}
        {(showModal === 'add' || showModal === 'edit') && (
          <div className="modal-backdrop" onClick={handleCloseModal}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
              <header className="modal-header">
                <h2>{showModal === 'add' ? '✨ Add New Catalog Product' : '✏️ Edit Catalog Product'}</h2>
                <button className="modal-close-btn" onClick={handleCloseModal}>✕</button>
              </header>

              <form onSubmit={handleSave}>
                <div className="modal-body">
                  <div className="form-group">
                    <label>Product Name*</label>
                    <input
                      type="text"
                      className="form-input"
                      placeholder="e.g. Fresh Red Strawberries"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    />
                    {formErrors.name && <span style={{ color: '#ef4444', fontSize: '0.8rem', fontWeight: 600 }}>{formErrors.name}</span>}
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label>Category*</label>
                      <select
                        className="form-input"
                        value={formData.category}
                        onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                      >
                        {CATEGORIES.map((cat) => (
                          <option key={cat} value={cat}>{cat}</option>
                        ))}
                      </select>
                      {formErrors.category && <span style={{ color: '#ef4444', fontSize: '0.8rem' }}>{formErrors.category}</span>}
                    </div>

                    <div className="form-group">
                      <label>Subcategory</label>
                      <input
                        type="text"
                        className="form-input"
                        placeholder="e.g. Fruits"
                        value={formData.subcategory}
                        onChange={(e) => setFormData({ ...formData, subcategory: e.target.value })}
                      />
                    </div>
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label>Selling Price (₹)*</label>
                      <input
                        type="number"
                        className="form-input"
                        placeholder="e.g. 199"
                        value={formData.price}
                        onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                      />
                      {formErrors.price && <span style={{ color: '#ef4444', fontSize: '0.8rem', fontWeight: 600 }}>{formErrors.price}</span>}
                    </div>

                    <div className="form-group">
                      <label>Original Price (₹)</label>
                      <input
                        type="number"
                        className="form-input"
                        placeholder="e.g. 299"
                        value={formData.originalPrice}
                        onChange={(e) => setFormData({ ...formData, originalPrice: e.target.value })}
                      />
                      {formErrors.originalPrice && <span style={{ color: '#ef4444', fontSize: '0.8rem', fontWeight: 600 }}>{formErrors.originalPrice}</span>}
                    </div>
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label>Stock Level*</label>
                      <input
                        type="number"
                        className="form-input"
                        placeholder="e.g. 150"
                        value={formData.stock}
                        onChange={(e) => setFormData({ ...formData, stock: e.target.value })}
                      />
                      {formErrors.stock && <span style={{ color: '#ef4444', fontSize: '0.8rem', fontWeight: 600 }}>{formErrors.stock}</span>}
                    </div>

                    <div className="form-group">
                      <label>Image URL</label>
                      <input
                        type="text"
                        className="form-input"
                        placeholder="https://images.unsplash.com/photo-..."
                        value={formData.image}
                        onChange={(e) => setFormData({ ...formData, image: e.target.value })}
                      />
                    </div>
                  </div>

                  <div className="form-group">
                    <label>Description</label>
                    <textarea
                      className="form-input form-textarea"
                      placeholder="Describe the product features, quantity, weight, benefits..."
                      value={formData.description}
                      onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    />
                  </div>

                  <div className="checkbox-row">
                    <label className="checkbox-label">
                      <input
                        type="checkbox"
                        checked={formData.featured}
                        onChange={(e) => setFormData({ ...formData, featured: e.target.checked })}
                      />
                      Featured Pick
                    </label>
                    <label className="checkbox-label">
                      <input
                        type="checkbox"
                        checked={formData.isNew}
                        onChange={(e) => setFormData({ ...formData, isNew: e.target.checked })}
                      />
                      New Arrival
                    </label>
                  </div>
                </div>

                <footer className="modal-footer">
                  <button type="button" className="btn btn-secondary" onClick={handleCloseModal} disabled={saving}>
                    Cancel
                  </button>
                  <button type="submit" className="btn btn-primary" disabled={saving}>
                    {saving ? <div className="spinner-sm" /> : showModal === 'add' ? 'Create' : 'Save Changes'}
                  </button>
                </footer>
              </form>
            </div>
          </div>
        )}

        {/* Delete Confirmation Modal */}
        {showModal === 'delete' && selectedProduct && (
          <div className="modal-backdrop" onClick={handleCloseModal}>
            <div className="modal-content" style={{ maxWidth: '400px' }} onClick={(e) => e.stopPropagation()}>
              <header className="modal-header">
                <h2>⚠️ Delete Product</h2>
                <button className="modal-close-btn" onClick={handleCloseModal}>✕</button>
              </header>
              <div className="modal-body">
                <p>Are you sure you want to delete <strong>{selectedProduct.name}</strong>?</p>
                <p style={{ color: 'var(--admin-text-muted)', fontSize: '0.85rem', margin: '8px 0 0 0' }}>
                  This operation is irreversible and will remove the item from all inventory counts.
                </p>
              </div>
              <footer className="modal-footer">
                <button className="btn btn-secondary" onClick={handleCloseModal} disabled={saving}>
                  Cancel
                </button>
                <button className="btn btn-danger" onClick={handleDelete} disabled={saving}>
                  {saving ? <div className="spinner-sm" /> : 'Confirm Delete'}
                </button>
              </footer>
            </div>
          </div>
        )}

        {/* Toasts */}
        <div className="toast-container">
          {toasts.map((t) => (
            <div key={t.id} className={`toast ${t.type}`}>
              <span>{t.type === 'error' ? '❌' : t.type === 'info' ? 'ℹ️' : '✅'}</span>
              <span>{t.message}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default AdminProducts;
